package com.example.urlshortener.orchestration.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="workflow_events")
public class WorkflowEvent { @Id private UUID id; @Column(nullable=false) private UUID runId; @Column(nullable=false) private Instant occurredAt; @Column(nullable=false,length=40) private String actorType; @Column(nullable=false,length=100) private String action; @Column(nullable=false,length=80) private String node; @Column(nullable=false,length=30) private String result; @Column(nullable=false,columnDefinition="text") private String reason; @Column(columnDefinition="text") private String payload;
 protected WorkflowEvent(){} public WorkflowEvent(UUID runId,String actorType,String action,String node,String result,String reason,String payload){this.id=UUID.randomUUID();this.runId=runId;this.occurredAt=Instant.now();this.actorType=actorType;this.action=action;this.node=node;this.result=result;this.reason=reason;this.payload=payload;}
 public UUID getId(){return id;} public UUID getRunId(){return runId;} public Instant getOccurredAt(){return occurredAt;} public String getActorType(){return actorType;} public String getAction(){return action;} public String getNode(){return node;} public String getResult(){return result;} public String getReason(){return reason;} public String getPayload(){return payload;}}
